/* Same-page opening: issued ID -> corridor -> five steps -> closed door.
   No access reader, handle interaction, door opening, room interior or next scene. */
(() => {
  'use strict';

  const $ = selector => document.querySelector(selector);
  const root = $('#opening-sequence');
  const cardScene = $('#issuance-scene');
  const entryButton = $('#enter-button');
  const resetButton = $('#reset-button');
  const soundButton = $('#sound-button');
  const blackout = $('#scene-blackout');
  const camera = $('#opening-camera');
  const corridor = $('#corridor-background');
  const door = $('#door-background');
  const corridorPlate = $('#corridor-plate');
  const doorPlate = $('#door-plate');
  const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');

  // Transition/audio timing is shared by WebGL and the image fallback.
  // The true 3D camera lives in corridor-3d.js / SPACE; the photo scale below is fallback-only.
  const OPENING = Object.freeze({
    fadeOut: 720, quiet: 170, walk: 4000,
    steps: Object.freeze([280, 1030, 1780, 2530, 3280]), stepBob: 570,
    corridorScale: [1.015, 1.65], corridorOffsetY: 6
  });

  let phase = 'idle';
  let identity = null;
  let veilAnimation = null;
  let master = null;
  let masterContext = null;
  let stepCount = 0;
  let audibleSteps = 0;
  let worstDrift = 0;
  let shoeBuffer = null;
  let shoeDecode = null;
  let spatialScene = null;

  // Recorded women's high-heel Foley, CC0, OwlStorm / Freesound 151208.
  // Four .52-second footfalls at .60-second intervals, including natural sole/room tails.
  // Inline PCM also works when the original standalone page is opened via file://.
  // package.py refreshes this payload from assets/shoe-steps.wav.
  const SHOE_AUDIO_BASE64 = '';

  const clamp = (value, min = 0, max = 1) => Math.max(min, Math.min(max, value));
  const smooth = value => { const t = clamp(value); return t * t * (3 - 2 * t); };
  const mix = (from, to, amount) => from + (to - from) * amount;
  const pause = duration => new Promise(resolve => window.setTimeout(resolve, duration));

  function state(next) {
    phase = next;
    root.dataset.state = next;
  }

  function decodePlate(plate) {
    return plate.decode().then(() => plate.naturalWidth > 0).catch(() => false);
  }

  // Eager decode runs in the background while the ID is being filled out.
  const platesReady = new Promise(resolve => {
    const timeout = window.setTimeout(() => resolve(false), 10000);
    Promise.all([decodePlate(corridorPlate), decodePlate(doorPlate)]).then(results => {
      window.clearTimeout(timeout);
      resolve(results.every(Boolean));
    });
  });

  async function fadeBlack(to, duration) {
    const from = Number(getComputedStyle(blackout).opacity);
    veilAnimation?.cancel();
    blackout.style.opacity = String(from);
    if (!duration) { blackout.style.opacity = String(to); return; }
    veilAnimation = blackout.animate([{ opacity: from }, { opacity: to }], {
      duration, easing: 'ease-in-out', fill: 'forwards'
    });
    await veilAnimation.finished;
    blackout.style.opacity = String(to);
    veilAnimation.cancel();
    veilAnimation = null;
  }

  function audioOutput() {
    const audio = window.HNJ?.audio;
    if (!audio?.isEnabled()) return null;
    const context = audio.getContext();
    if (!context) return null;
    if (masterContext !== context) {
      master?.disconnect();
      masterContext = context;
      master = context.createGain();
      master.gain.value = document.hidden ? 0 : .8;
      master.connect(context.destination);
    }
    prepareShoeAudio(context);
    return { context, output: master };
  }

  function prepareShoeAudio(context) {
    if (!shoeDecode) {
      const bytes = Uint8Array.from(atob(SHOE_AUDIO_BASE64), char => char.charCodeAt(0));
      shoeDecode = context.decodeAudioData(bytes.buffer).then(buffer => {
        shoeBuffer = buffer;
        root.dataset.footstepAudio = 'recorded-ready';
      }).catch(error => {
        root.dataset.footstepAudio = 'unavailable';
        console.warn('Footstep audio:', error.message);
      });
    }
    return shoeDecode;
  }

  function syncSound() {
    // The original button and preference remain the single source of truth.
    const enabled = window.HNJ?.audio.isEnabled() && !document.hidden;
    if (enabled) audioOutput();
    if (master && masterContext) {
      master.gain.cancelScheduledValues(masterContext.currentTime);
      master.gain.setTargetAtTime(enabled ? .8 : 0, masterContext.currentTime, .008);
    }
  }
  soundButton.addEventListener('click', syncSound);
  document.addEventListener('visibilitychange', syncSound);

  function shoeStep(index) {
    if (document.hidden) return false;
    const audio = audioOutput();
    if (!audio || !shoeBuffer || audio.context.state !== 'running') return false;
    const { context, output } = audio;
    const time = context.currentTime;
    const source = context.createBufferSource();
    const body = context.createBiquadFilter();
    const level = context.createGain();
    const position = context.createStereoPanner();
    const reflection = context.createDelay(.1);
    const reflectedLevel = context.createGain();
    source.buffer = shoeBuffer;
    body.type = 'highpass';
    body.frequency.value = 140;
    body.Q.value = .7;
    level.gain.value = .60;
    position.pan.value = index % 2 ? .065 : -.065;
    // Light hard-floor heel/sole contact; no added bass, just a very quiet short reflection.
    reflection.delayTime.value = .045;
    reflectedLevel.gain.value = .05;
    source.connect(body).connect(level).connect(position).connect(output);
    level.connect(reflection).connect(reflectedLevel).connect(output);
    source.start(time, (index % 4) * .6, .52);
    source.onended = () => {
      window.setTimeout(() => {
        [source, body, level, position, reflection, reflectedLevel].forEach(node => node.disconnect());
      }, 100);
    };
    return true;
  }

  function renderWalk(progress, elapsed) {
    const travel = smooth(progress);
    const scale = mix(...OPENING.corridorScale, travel);
    // A single uninterrupted camera approach: no second photograph appears or fades in.
    // The small downward reframe keeps the warm light and complete door in view at arrival.
    corridor.style.transform = `translateY(${OPENING.corridorOffsetY * travel}%) scale(${scale})`;
    corridor.style.opacity = '1';
    door.style.opacity = '0';

    // Five light, sub-two-pixel impulses share the exact same clock as the footsteps.
    let bob = 0;
    let sway = 0;
    OPENING.steps.forEach((step, index) => {
      const since = elapsed - step;
      if (since >= 0 && since < OPENING.stepBob) {
        const pulse = Math.sin(since / OPENING.stepBob * Math.PI) * (1 - since / OPENING.stepBob);
        bob += pulse * 1.7;
        sway += pulse * (index % 2 ? -.55 : .55);
      }
    });
    camera.style.transform = `translate3d(${sway}px,${bob}px,0)`;
    spatialScene?.render(progress, bob, sway);
    root.dataset.progress = progress.toFixed(3);
  }

  function settleAtDoor() {
    corridor.style.opacity = '1';
    corridor.style.transform = `translateY(${OPENING.corridorOffsetY}%) scale(${OPENING.corridorScale[1]})`;
    door.style.opacity = '0';
    camera.style.transform = 'translate3d(0,0,0)';
    corridorPlate.removeAttribute('aria-hidden');
    doorPlate.setAttribute('aria-hidden', 'true');
    corridorPlate.alt = '따뜻한 조명 아래 닫혀 있는 조사실 문 앞';
    spatialScene?.render(1, 0, 0);
    root.dataset.progress = '1.000';
  }

  function walkToDoor() {
    if (reducedMotion.matches) { settleAtDoor(); return Promise.resolve(); }
    return new Promise(resolve => {
      let elapsed = 0;
      let previous = null;
      let frames = 0;
      function frame(timestamp) {
        if (document.hidden) { previous = null; requestAnimationFrame(frame); return; }
        if (previous !== null) elapsed += Math.min(timestamp - previous, 64);
        previous = timestamp;
        elapsed = Math.min(elapsed, OPENING.walk);
        while (stepCount < OPENING.steps.length && elapsed >= OPENING.steps[stepCount]) {
          worstDrift = Math.max(worstDrift, elapsed - OPENING.steps[stepCount]);
          if (shoeStep(stepCount)) audibleSteps++;
          stepCount++;
          root.dataset.footsteps = String(stepCount);
          root.dataset.audibleSteps = String(audibleSteps);
          root.dataset.stepDriftMs = worstDrift.toFixed(1);
        }
        renderWalk(elapsed / OPENING.walk, elapsed);
        root.dataset.frames = String(++frames);
        if (elapsed < OPENING.walk) requestAnimationFrame(frame);
        else { settleAtDoor(); resolve(); }
      }
      requestAnimationFrame(frame);
    });
  }

  async function startOpening(event) {
    if (phase !== 'idle' || !event.detail || event.detail !== window.HNJ?.getIdentity()) return;
    identity = event.detail;
    state('transitioning');
    entryButton.disabled = resetButton.disabled = true;
    entryButton.blur();
    cardScene.inert = true;
    blackout.classList.add('is-active');
    // This call is deliberately synchronous within the entry click: unlock Web Audio now.
    audioOutput();
    try {
      await fadeBlack(1, reducedMotion.matches ? 120 : OPENING.fadeOut);
      // Build/compile behind the completed blackout, so the ID-card motion remains intact.
      // The existing photographic path is retained only for browsers without WebGL2.
      spatialScene = await window.HNJCorridor3D?.create($('#opening-stage')) || null;
      if (!spatialScene && !await platesReady) throw new Error('Opening environment could not be prepared.');
      if (!spatialScene) root.dataset.renderer = 'image-fallback';
      await pause(reducedMotion.matches ? 0 : OPENING.quiet);
      cardScene.hidden = true;
      cardScene.setAttribute('aria-hidden', 'true');
      document.body.classList.add('opening-active');
      renderWalk(0, 0);
      root.hidden = false;
      spatialScene?.resize(); // The stage now has its real desktop/portrait dimensions.
      root.removeAttribute('aria-hidden');
      state('corridor');
      root.focus({ preventScroll: true });
      // A clean cut after the short black pause: the corridor never fades in from black.
      await fadeBlack(0, 0);
      blackout.classList.remove('is-active');
      state('walking');
      await walkToDoor();
      state('arrived');
      root.setAttribute('aria-label', '닫힌 조사실 문 앞');
      // NEXT SCENE HOOK: the closed door is now stable. Add the actual card slot and
      // door interactions to #door-interaction-layer in a later task, not here.
      window.dispatchEvent(new CustomEvent('investigation:arrived', { detail: identity }));
    } catch (error) {
      // Recover to the same issued card if local assets are missing. No dummy page or alert.
      root.hidden = true;
      root.setAttribute('aria-hidden', 'true');
      document.body.classList.remove('opening-active');
      cardScene.hidden = false;
      cardScene.removeAttribute('aria-hidden');
      cardScene.inert = false;
      entryButton.disabled = resetButton.disabled = false;
      await fadeBlack(0, 200);
      blackout.classList.remove('is-active');
      state('idle');
      console.warn('Investigation opening:', error.message);
    }
  }

  window.addEventListener('investigation:enter', startOpening);
})();
